<script setup>
import {ref} from 'vue';import {Head,Link,useForm} from '@inertiajs/vue3';import AppLayout from '../Layouts/AppLayout.vue';import AppModal from '../Components/AppModal.vue';import FormErrors from '../Components/FormErrors.vue';import {useExamContext} from '../exam-context';
defineProps({results:Object});const {base,context}=useExamContext();const selected=ref(null);const form=useForm({scores:{}});function show(result){selected.value=result;form.clearErrors();form.scores=Object.fromEntries(result.questions.filter(question=>(question.kind||'mcq')!=='mcq').map(question=>[question.id,result.manual_scores?.[question.id]??0]));}
</script>
<template><Head :title="'Kết quả · '+context.name"/><AppLayout><div class="page-heading"><div><h1>Bài làm & kết quả {{context.name}}</h1><p>Trắc nghiệm chấm tự động; tự luận và bài nói được chấm theo điểm tối đa từng câu.</p></div></div><div class="card"><div class="tablewrap"><table><thead><tr><th>Thí sinh</th><th>Đề</th><th>Lượt</th><th>Trạng thái</th><th>Điểm</th><th>Thao tác</th></tr></thead><tbody><tr v-for="result in results.data" :key="result.id"><td>{{result.student.name}}<small class="cell-meta">{{result.student.email}}</small></td><td class="table-title">{{result.exam.title}}</td><td>{{result.attempt_number}}</td><td><span class="pill">{{!result.submitted_at?'Đang làm':result.graded_at?'Đã chấm':'Chờ chấm'}}</span></td><td>{{result.total_points??'—'}}</td><td><button class="secondary" @click="show(result)">Xem / chấm bài</button></td></tr><tr v-if="!results.data.length"><td colspan="6" class="empty-state">Chưa có bài làm trong phân hệ này.</td></tr></tbody></table></div><div class="pagination"><Link v-if="results.prev_page_url" :href="results.prev_page_url">← Trước</Link><span>Trang {{results.current_page}} / {{results.last_page}}</span><Link v-if="results.next_page_url" :href="results.next_page_url">Tiếp →</Link></div></div><AppModal :open="!!selected" :title="'Bài làm · '+(selected?.student.name||'')" wide :busy="form.processing" @close="selected=null"><form v-if="selected" @submit.prevent="form.put(base+'/results/'+selected.id,{onSuccess:()=>selected=null})"><FormErrors :errors="form.errors"/><p class="notice">{{selected.exam.title}} · Lượt {{selected.attempt_number}}{{selected.submitted_at?' · Đã nộp':' · Chưa nộp, chưa thể chấm'}}</p><section v-for="(question,index) in selected.questions" :key="question.id" class="grade-question"><h2>Câu {{index+1}} · {{question.max_points||1}} điểm</h2><p>{{question.content}}</p><div v-if="(question.kind||'mcq')==='speaking'"><audio v-if="selected.answers?.[question.id]==='recorded'" :src="base+'/results/'+selected.id+'/recordings/'+question.id" controls/><p v-else class="muted">Chưa có bài ghi âm.</p></div><div v-else class="result-answer">{{selected.answers?.[question.id]||'Chưa trả lời'}}</div><p v-if="(question.kind||'mcq')==='mcq'" class="muted">Đáp án đúng: {{question.correct_option}} · {{selected.answers?.[question.id]===question.correct_option?'Đúng':'Sai / chưa trả lời'}}</p><label v-else :for="'score-'+question.id">Điểm chấm<input :id="'score-'+question.id" v-model.number="form.scores[question.id]" type="number" min="0" :max="question.max_points||1" step="0.1" required :disabled="!selected.submitted_at"/></label></section><div class="modal-actions"><button type="button" class="secondary" @click="selected=null">Đóng</button><button v-if="Object.keys(form.scores).length" :disabled="form.processing||!selected.submitted_at">Lưu điểm chấm</button></div></form></AppModal></AppLayout></template>
